-- The venue's two standard tasting menus (buffet / plated) were constants in the
-- source code, and nothing in the app could change them. They now live in a table
-- the venue edits at /admin/menus - by hand or by uploading a sample Word menu -
-- and an event's menu tab can load them with one click. The AI import of an
-- event's own menu document also uses them as the example of this venue's format.

create table if not exists default_menus (
  menu_type text primary key check (menu_type in ('buffet', 'plated')),
  title text,
  subtitle text,
  linens_note text,
  -- [{ label: string, note: string | null, items: string[] }, ...]
  sections jsonb not null default '[]'::jsonb,
  footer_notes jsonb not null default '[]'::jsonb,
  updated_at timestamptz not null default now()
);

alter table default_menus enable row level security;
create policy "default_menus select" on default_menus for select using (is_staff_member());
create policy "default_menus insert" on default_menus for insert with check (has_permission('venue_settings', 'write'));
create policy "default_menus update" on default_menus for update
  using (has_permission('venue_settings', 'write')) with check (has_permission('venue_settings', 'write'));
create policy "default_menus delete" on default_menus for delete using (has_permission('venue_settings', 'write'));

insert into default_menus (menu_type, title, subtitle, linens_note, sections, footer_notes)
values ('buffet', $t$תפריט טעימות מטבחים פתוחים$t$, $t$תפריט השראה עונתי-מקומי המוגש ממטבחים פתוחים$t$, $t$לבן / שמנת / שחור$t$, $t$[{"label": "הגינה שלנו", "note": "2 עמדות לבחירה", "items": []}, {"label": "דגים נאים", "note": null, "items": ["לאפה חסה, סביצ׳ה מוסר ים, עשבי תבלין, רוטב דגים וליים", "סשימי טונה בלו פין, פונזו טחינה ופוריקקה", "טרטר טונה, סויה, עשבים ירוקים ושאלוט"]}, {"label": "בשר נא & טאקו", "note": null, "items": ["ברוסקטה בגריל פחמים, טרטר בקר מעושן, שקדים קצוצים, בצל סגול ועשבי תבלין", "חלת מרווה ודבש, קרפצ'יו בקר, רכז רימונים וסלט רוקט", "טאקו קמח תירס, בשר מפורק, איולי צ'יפוטלה ופיקו דה גאיו"]}, {"label": "מזרח תיכון חדש", "note": null, "items": ["מסאבחה חמימה עבודת יד במכתש ועלי", "בייגלה ירושלמי", "קטאייף טלה וצנוברים", "טחינה הר ברכה", "אריסה", "סחוג ירוק", "סלסה של עגבניות שרופות"]}, {"label": "ארוחת ערב", "note": null, "items": []}, {"label": "על השולחן", "note": null, "items": ["פוקצ'ה \"עננים\"", "שמן זית ובלסמי", "סלסה של עגבניות מגי שרופות", "באבא גנוש", "צלחת חריפים ירוקים ושום קונפי"]}, {"label": "ירק ואנטיפסטי", "note": "סלט עלים עם פרי עונתי ושאלוט מוחמץ ובנוסף 4 אופציות לבחירה בהתאם לעונה", "items": ["קינואה אורגנית, ארבע ירוקים, דובדבנים מיובשים וג'עלה", "סלקים צלויים, סלרי, פיסטוק ורכז רימונים", "עגבניות שוק, בצל ירוק, פלפל חריף ואורגנו טרי", "סלט מלפפונים בייבי, בצל ירוק, כוסברה, בוטנים וצ'ילי אדום", "כרוב צלוי על פחמים, גרגירי חומוס מעושנים, שיפקה ובצל סגול"]}, {"label": "מטבח אש וגריל", "note": null, "items": ["מבחר נתחי בשר מהקצב שלנו, מוגשים בפריסה עם צ'ימיצ'ורי", "פלאט איירון סטייק", "רוסט שייטל", "סינטה מפרה בכירה"]}, {"label": "ירקות מהגריל", "note": null, "items": ["קרעי תפו״א באטר", "בטטה מדורה", "שעועית ירוקה בגריל (בעונה)"]}, {"label": "עמדת מחבת ברזל יצוקה", "note": "1 לבחירה", "items": ["מסאחן עוף קונפי עם בצל וסומק, לחוח תיימני, ירקות בגריל, עשבי תבלין ירוקים וטחינה הר ברכה", "סופלאקי פרגיות, זוקיני צלוי, אחו בלאנקו, עשבי תבלין ושקדים קצוצים"]}, {"label": "עמדת תנור אבני שמוט", "note": "1 לבחירה", "items": ["פילה דג ים בתנור אבן, פסטה בוסיאטה אליו אוליו, קונפי שום, ועגבניות שרי תמר", "פילה דג ים בתנור אבן, פסטה בלרינה, ארביאטה עגבניות ופאנגריטטה"]}, {"label": "קינוחים", "note": null, "items": ["מוס שוקולד, שמן זית ומלח גס", "קראנץ שמרים חמה מהתנור", "בראד פודינג, קצפת מתוקה וקרמל מלוח", "עמדת גלידה אמריקאית בטעם וניל עם מלא תוספות ורטבים"]}, {"label": "עמדת לייט נייט – לא יוגש בטעימה", "note": "1 לבחירה", "items": ["סמאש בורגר, בצל מקורמל, איולי עשבים וסלט רוקט", "נקניקיה גרמנית בלחמניית פרעצל, כרוב כבוש ובצל מטוגן", "שניצל בלחמניית חלה מתוקה, חציל מטוגן, מטבוחה, טחינה ועלים ירוקים", "בורקס \"באבא\" אוריגינל במילוי תפו\"א ותרד, טחינה, ביצים קשות, אריסה, חמוצים, סלסלת עגבניות"]}]$t$::jsonb, $t$["יין אדום, לבן ורוזה במזיגה מהבר (יקבי גולן)", "המטבח שלנו הוא מטבח עונתי ולכן יתכנו שינויים במנות בהתאם להיצע חומרי הגלם בשוק, לעונות השנה ולתקנות הכשרות", "מים וסודה בבקבוקי זכוכית על כל שולחן"]$t$::jsonb)
on conflict (menu_type) do nothing;

